/// HTTP client for the Worker API (`rust/api/`). The only file that makes
/// network calls to our backend.
///
/// Every request carries the signed-in user's Firebase ID token; the Worker
/// verifies it and derives the uid from it. Never send a uid in a body.
///
/// Request bodies come from Rust (`lib/src/rust/api/*.dart`, generated by
/// flutter_rust_bridge) so validation and JSON shape match the Worker exactly.
///
/// For tests, override [apiClientProvider] with a fake, or construct an
/// [ApiClient] with a `MockClient` and a fixed token (see
/// `test/core/api/api_client_test.dart`).
library;

import 'dart:async';
import 'dart:typed_data';

import 'package:app/core/api/api_exception.dart';
import 'package:app/core/bootstrap.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter_dotenv/flutter_dotenv.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:http/http.dart' as http;

/// Returns the current user's ID token, or `null` when nobody is signed in.
typedef TokenProvider = Future<String?> Function();

class ApiClient {
  ApiClient({
    required TokenProvider tokenProvider,
    required String baseUrl,
    http.Client? httpClient,
  }) : _token = tokenProvider,
       _baseUrl = baseUrl,
       _http = httpClient ?? http.Client();

  final TokenProvider _token;
  final String _baseUrl;
  final http.Client _http;

  static const _timeout = Duration(seconds: 15);

  /// `GET` — returns the response body (JSON text).
  Future<String> getJson(String path) => _send('GET', path);

  /// `POST` with an already-encoded JSON string. Returns the response body.
  Future<String> postJson(String path, String jsonBody) =>
      _send('POST', path, jsonBody);

  /// `PUT` with an already-encoded JSON string. Returns the response body.
  Future<String> putJson(String path, String jsonBody) =>
      _send('PUT', path, jsonBody);

  /// `DELETE`. Completes normally on any 2xx.
  Future<void> delete(String path) => _send('DELETE', path);

  /// `POST` raw bytes (an upload). Returns the response body (JSON text).
  Future<String> postBytes(
    String path,
    Uint8List bytes, {
    String contentType = 'application/octet-stream',
  }) async => (await _request(
    'POST',
    path,
    bodyBytes: bytes,
    contentType: contentType,
  )).body;

  /// `GET` raw bytes (a download). Needs the auth header, so it cannot be an
  /// `Image.network` URL — fetch here and use `Image.memory`.
  Future<Uint8List> getBytes(String path) async =>
      (await _request('GET', path)).bodyBytes;

  /// Text-bodied request (JSON). Returns the response body.
  Future<String> _send(String method, String path, [String? jsonBody]) async =>
      (await _request(
        method,
        path,
        bodyText: jsonBody,
        contentType: jsonBody == null ? null : 'application/json',
      )).body;

  /// Throws an [ApiException] on any failure; never returns a non-2xx response.
  Future<http.Response> _request(
    String method,
    String path, {
    String? bodyText,
    Uint8List? bodyBytes,
    String? contentType,
  }) async {
    final http.Response response;
    try {
      final token = await _token();
      if (token == null) throw ApiUnauthenticatedException(path);

      final request = http.Request(method, Uri.parse('$_baseUrl$path'))
        ..headers['Authorization'] = 'Bearer $token';
      if (contentType != null) request.headers['Content-Type'] = contentType;
      if (bodyText != null) request.body = bodyText;
      if (bodyBytes != null) request.bodyBytes = bodyBytes;
      response = await http.Response.fromStream(
        await _http.send(request).timeout(_timeout),
      );
    } on ApiException {
      rethrow;
    } on Exception catch (e, st) {
      // Offline, DNS, TLS, timeout, token refresh failure.
      throw ApiNetworkException(path, e, st);
    }

    if (response.statusCode < 200 || response.statusCode >= 300) {
      throw ApiResponseException.fromBody(
        path,
        response.statusCode,
        response.body,
      );
    }
    return response;
  }

  /// `GET /health` — the one unauthenticated route. Never throws.
  Future<bool> isReachable() async {
    try {
      final response = await _http
          .get(Uri.parse('$_baseUrl/health'))
          .timeout(const Duration(seconds: 5));
      return response.statusCode == 200;
    } on Exception catch (e) {
      debugPrint('[api] health check failed for $_baseUrl: $e');
      return false;
    }
  }
}

final apiClientProvider = Provider<ApiClient>((ref) {
  final firebaseReady = ref.watch(firebaseReadyProvider);
  return ApiClient(
    baseUrl: dotenv.env['API_BASE_URL'] ?? '',
    // `FirebaseAuth.instance` throws if Firebase never initialized, so it is
    // only touched once bootstrap reported success.
    tokenProvider: () async =>
        firebaseReady ? FirebaseAuth.instance.currentUser?.getIdToken() : null,
  );
});
